export const LANGUAGE_LIST = [
  { code: 'fr' as LanguageCode, name: 'Français', nativeName: 'Français', dir: 'ltr' },
  { code: 'en' as LanguageCode, name: 'English', nativeName: 'English', dir: 'ltr' },
  { code: 'ar' as LanguageCode, name: 'Arabic', nativeName: 'العربية', dir: 'rtl' },
  { code: 'de' as LanguageCode, name: 'German', nativeName: 'Deutsch', dir: 'ltr' },
  { code: 'es' as LanguageCode, name: 'Spanish', nativeName: 'Español', dir: 'ltr' },
  { code: 'it' as LanguageCode, name: 'Italian', nativeName: 'Italiano', dir: 'ltr' },
  { code: 'pt' as LanguageCode, name: 'Portuguese', nativeName: 'Português', dir: 'ltr' },
  { code: 'nl' as LanguageCode, name: 'Dutch', nativeName: 'Nederlands', dir: 'ltr' },
  { code: 'ur' as LanguageCode, name: 'Urdu', nativeName: 'اردو', dir: 'rtl' },
  { code: 'bn' as LanguageCode, name: 'Bengali', nativeName: 'বাংলা', dir: 'ltr' },
  { code: 'hi' as LanguageCode, name: 'Hindi', nativeName: 'हिन्दी', dir: 'ltr' },
  { code: 'fa' as LanguageCode, name: 'Persian', nativeName: 'فارسی', dir: 'rtl' },
  { code: 'ru' as LanguageCode, name: 'Russian', nativeName: 'Русский', dir: 'ltr' },
  { code: 'zh' as LanguageCode, name: 'Chinese', nativeName: '中文', dir: 'ltr' },
  { code: 'tr' as LanguageCode, name: 'Turkish', nativeName: 'Türkçe', dir: 'ltr' },
  { code: 'id' as LanguageCode, name: 'Indonesian', nativeName: 'Bahasa Indonesia', dir: 'ltr' },
  { code: 'ms' as LanguageCode, name: 'Malay', nativeName: 'Bahasa Melayu', dir: 'ltr' },
  { code: 'sw' as LanguageCode, name: 'Swahili', nativeName: 'Kiswahili', dir: 'ltr' },
  { code: 'pl' as LanguageCode, name: 'Polish', nativeName: 'Polski', dir: 'ltr' },
  { code: 'uk' as LanguageCode, name: 'Ukrainian', nativeName: 'Українська', dir: 'ltr' },
];

export const getTranslations = (lang: LanguageCode): TranslationKeys => {
  return { ...translations.fr, ...(translations[lang] || {}) } as TranslationKeys;
};

export const getLanguageDirection = (lang: LanguageCode): 'ltr' | 'rtl' => {
  const langInfo = LANGUAGE_LIST.find(l => l.code === lang);
  return (langInfo?.dir as 'ltr' | 'rtl') || 'ltr';
};

export default translations;
